/**
 * Statement-level node types the TODO comment may attach to. When a
 * `FileLogger` instantiation is nested inside an expression, we walk up to
 * the nearest enclosing statement so the comment lands on its own line
 * immediately above — never inline with the `new` expression.
 */
const STATEMENT_TYPES: ReadonlySet<string> = new Set([
    "ExpressionStatement",
    "VariableDeclaration",
    "ReturnStatement",
    "ThrowStatement",
    "ExportDefaultDeclaration",
    "ExportNamedDeclaration",
    "ClassProperty",
    "PropertyDefinition",
    "ClassPrivateProperty",
])

/**
 * Collects the namespace bindings that alias the whole `typeorm` module, so
 * `FileLogger` reached via a member access (`typeorm.FileLogger`) is tracked:
 *
 *   import * as typeorm from "typeorm"     → { "typeorm" }
 *   const typeorm = require("typeorm")     → { "typeorm" }
 */
const getNamespaceNames = (root: Collection, j: JSCodeshift): Set<string> => {
    const namespaces = new Set<string>()

    // ESM: `import * as ns from "typeorm"`
    root.find(j.ImportDeclaration, {
        source: { value: "typeorm" },
    }).forEach((importPath) => {
        for (const spec of importPath.node.specifiers ?? []) {
            if (
                spec.type === "ImportNamespaceSpecifier" &&
                spec.local?.type === "Identifier"
            ) {
                namespaces.add(spec.local.name)
            }
        }
    })

    // CommonJS: `const ns = require("typeorm")`
    root.find(j.CallExpression, {
        callee: { type: "Identifier", name: "require" },
    }).forEach((callPath) => {
        const [arg] = callPath.node.arguments
        if (!arg || getStringValue(arg) !== "typeorm") return

        const parent = callPath.parent.node
        if (parent.type !== "VariableDeclarator") return
        const id = parent.id
        if (id.type === "Identifier") {
            namespaces.add(id.name)
        }
    })

    return namespaces
}

/**
 * Returns the key of an object property as a string, or null for computed /
 * non-identifier keys we can't statically resolve.
 */
const getPropertyKeyName = (prop: {
    key: ASTNode
}): string | null => {
    if (prop.key.type === "Identifier") return prop.key.name
    return getStringValue(prop.key)
}

const isNullish = (node: ASTNode): boolean =>
    (node.type === "Identifier" && node.name === "undefined") ||
    node.type === "NullLiteral" ||
    (node.type === "Literal" && node.value === null)

/**
 * A log path string literal is "safe" (needs no warning) only when it is an
 * absolute POSIX path or a Windows UNC path. Everything else is relative and
 * would resolve differently from `process.cwd()`.
 */
const isAbsolutePathLiteral = (value: string): boolean =>
    value.startsWith("/") || value.startsWith("\\\\")

/**
 * Decides whether an inline `{ ... }` file-logger options object warrants a
 * warning based on its `logPath` property.
 */
const objectNeedsWarning = (obj: ObjectExpression): boolean => {
    let logPathValue: ASTNode | null = null
    let hasSpread = false

    for (const prop of obj.properties) {
        if (prop.type !== "ObjectProperty" && prop.type !== "Property") {
            // SpreadElement / SpreadProperty — logPath may hide inside it.
            hasSpread = true
            continue
        }
        if (getPropertyKeyName(prop) === "logPath") {
            logPathValue = prop.value as ASTNode
        }
    }

    if (logPathValue === null) {
        // No explicit logPath. If the object is composed purely of spreads we
        // cannot know whether logPath is present, so stay silent. Otherwise
        // the default (relative) path applies and we warn.
        return !hasSpread
    }

    if (isNullish(logPathValue)) return true

    const literal = getStringValue(logPathValue)
    if (literal !== null) {
        // Absolute literals are fine; relative literals need the warning.
        return !isAbsolutePathLiteral(literal)
    }

    // Non-literal expression (e.g. `path.resolve(...)`) — assume the author
    // built an absolute path deliberately and stay silent.
    return false
}

/**
 * Determines whether a `new FileLogger(...)` call should be flagged, based on
 * its `fileLoggerOptions` (second) argument, which is where `logPath` lives.
 */
const instantiationNeedsWarning = (args: ASTNode[]): boolean => {
    const optionsArg = args[1]

    // No options argument at all → default (relative) log path.
    if (optionsArg === undefined) return true

    // `undefined` / `null` options → default (relative) log path.
    if (isNullish(optionsArg)) return true

    if (optionsArg.type === "ObjectExpression") {
        return objectNeedsWarning(optionsArg)
    }

    // A dynamic (non-object-literal) options value can't be inspected.
    return false
}

/**
 * Walks up from an AST path to the nearest enclosing statement node,
 * bubbling through any `export` wrapper so the comment lands above `export`.
 */
const findEnclosingStatement = (start: ASTPath): ASTNode | null => {
    let cursor: ASTPath | null = start
    while (cursor && !STATEMENT_TYPES.has(cursor.node.type)) {
        cursor = cursor.parent
    }
    if (!cursor) return null

    let statement: ASTPath = cursor
    while (
        statement.parent &&
        (statement.parent.node.type === "ExportNamedDeclaration" ||
            statement.parent.node.type === "ExportDefaultDeclaration")
    ) {
        statement = statement.parent
    }

    return statement.node
}

